ALIASES={"plastic":"plastic","plastic_bottle":"plastic","bottle":"plastic","pet":"plastic","paper":"paper","newspaper":"paper","cardboard":"cardboard","carton":"cardboard","glass":"glass","metal":"metal","can":"metal","aluminium":"metal","aluminum":"metal","organic":"organic","food":"organic","food_waste":"organic","ewaste":"ewaste","e_waste":"ewaste","electronics":"ewaste","battery":"battery","batteries":"battery","textile":"textile","cloth":"textile","clothes":"textile","hazardous":"hazardous","chemical":"hazardous","trash":"general","garbage":"general","waste":"general","general":"general"}
def normalize_category(label):
    return ALIASES.get(str(label).strip().lower().replace(" ","_").replace("-","_"))
def get_guidance(category): return WASTE_GUIDE.get(category,WASTE_GUIDE["general"])
